	double dArray[dimension];
	double dMin = 0.0, dMax = 0.0;

	double t1 = omp_get_wtime();

	#pragma omp parallel
	{

		#pragma omp for reduction(min: dMin) reduction(max: dMax)
		for (i = 0; i < dimension; i++)
		{
			dArray[i] = func(i);
			dMin = fmin(dMin, dArray[i]);
			dMax = fmax(dMax, dArray[i]);
		}

	} // end omp parallel

	double t2 = omp_get_wtime();
	printf("Computation took %.3lf seconds.\n", t2 - t1);
	printf("dMin is %.3lf.\n", dMin);
	printf("dMax is %.3lf.\n", dMax);

	return 0;
},"Function Name: main

