  scanf("%d",&n);
  starttime=omp_get_wtime();

  #pragma omp parallel
  #pragma omp single
  {
    fibonacci=fib(n);
  }

  printf("fib(%d)=%d \n",n,fibonacci);
  printf("calculation took %lf sec\n",omp_get_wtime()-starttime);
  return 0;
},"Function Name: main

