        (void)sched_getaffinity(0, sizeof(coremask2), &coremask2);
         cpuset_to_cstr(&coremask2, clbuf2);
         #pragma omp barrier
         printf("Hello from level 2: thread level 1=  %d, thread level 2= %d, on %s. (core affinity = %s)\n",
                 thread1, thread2, hnbuf2, clbuf2);
        }        
  }
  return(0);
