            }

            // potential before moving
            double vs = potential(a, b, c, x1, x2, x3);

            // move
            x1 = x1 + dx;
            x2 = x2 + dy;
            x3 = x3 + dz;

            // potential after moving
            double vh = potential(a, b, c, x1, x2, x3);

            double we = (1.0 - h * vs) * w;
            w = w - 0.5 * h * (vh * we + vs * w);

            chk = pow(x1 / a, 2) + pow(x2 / b, 2) + pow(x3 / c, 2);
