void get_dev_cos(double *mem, int s)
{
   int h, t, i;
   double * mem_dev_cpy;
   h = omp_get_initial_device();
   t = omp_get_default_device();

   if (omp_get_num_devices() < 1 || t < 0){
      printf(" ERROR: No device found.\n");
      exit(1);
   }

   mem_dev_cpy = (double *)omp_target_alloc( sizeof(double) * s, t);
   if(mem_dev_cpy == NULL){
      printf(" ERROR: No space left on device.\n");
      exit(1);
   }

                          /* dst  src */
   omp_target_memcpy(mem_dev_cpy, mem, sizeof(double)*s,
                              0,    0,
                              t,   h);

   #pragma omp target is_device_ptr(mem_dev_cpy) device(t)
   #pragma omp teams distribute parallel for
     for(i=0;i<s;i++){ mem_dev_cpy[i] = cos((double)i); } /* init data */

                   /* dst  src */
    omp_target_memcpy(mem, mem_dev_cpy, sizeof(double)*s,
                      0,             0,
                      h,             t);

    omp_target_free(mem_dev_cpy, t);
},

void async_memcpy() {
  int h_dev = omp_get_initial_device();
  int d_dev = omp_get_default_device();
  size_t dsize;
  float h_buf[N];
  void *d_buf;
  int i;

  /* allocate device memory */
  dsize = N * sizeof(float);
  d_buf = omp_target_alloc(dsize, d_dev);
  if (!d_buf)
    abort();

  /* set up host data */
  for (i = 0; i < N; i++) {
    h_buf[i] = i*0.1f;
  }

  /* copy data from host to device asynchronously */
  if (omp_target_memcpy_async(d_buf, h_buf, dsize, 0, 0, 
                              d_dev, h_dev, 0, NULL))
    abort();

  /* do some work here at the same time */
  do_work();

  /* wait for task completion */
  #pragma omp taskwait

  omp_target_free(d_buf, d_dev);
},

void async_work(int N, float *d_buf, float *h_buf)
{
   omp_depend_t obj;
   int d_dev, h_dev;
   size_t dsize;

   h_dev = omp_get_initial_device();
   d_dev = omp_get_default_device();
   dsize = N * sizeof(float);

   // initialize a depend object 'obj'
   #pragma omp depobj(obj) depend(out: d_buf[0:N])

   // start the async memcpy of s_buf to d_buf on device
   if (omp_target_memcpy_async(d_buf, h_buf, dsize, 0, 0, 
                               d_dev, h_dev, 1, &obj))
      abort();

   // do some useful work at the same time on host
   do_work(N, h_buf);

   // wait until memcpy finishes before using d_buf in the target region
   #pragma omp target is_device_ptr(d_buf) depend(depobj: obj)
   do_more_work(N, d_buf);
},

int main()
{

// CASE 1 Lambda defined in target region

   S s = S {0,1};

   #pragma omp target
   {   
      auto lambda1 = [&s]() { s.a = s.b * 2; };  
      s.b += 2;
      lambda1(); // s.a = 3 * 2 
   }   
   cout << s.a << " " << s.b << endl; //OUT 6 3

// CASE 2 Host defined lambda, Capture pointer to s

   s = {0,1};
   S *sp = &s;
   auto lambda2 = [sp]() {sp->a = sp->b * 2; };

   // closure object's sp attaches to corresponding s on target
   // construct
   #pragma omp target data map(sp[0])
   #pragma omp target
   {
      sp->b += 2;
      lambda2();
   }
   cout << s.a << " " << s.b << endl; //OUT 6 3

// CASE 3 Host defined lambda, Capture s by reference

   s = {0,1};
   auto lambda3 = [&s]() {s.a = s.b * 2; };

   // closure object's s refers to corresponding s in target
   // construct
   #pragma omp target data map(s)
   #pragma omp target
   {
      s.b += 2;
      lambda3();
   }
   cout << s.a << " " << s.b << endl; //OUT 6 3

// CASE 4 Host defined lambda, references static variable

   static S ss = {0,1};
   #pragma omp declare target enter(ss)
   auto lambda4 = [&]() {ss.a = ss.b * 2; };

   #pragma omp target map(always,from:ss)
   {
      ss.b += 2;
      lambda4();
   }
   cout << ss.a << " " << ss.b << endl; //OUT 6 3

   return 0;
},

