    for(int i=0; i<NT; i++) printf("thrd no %d\n",thrd_no());

    #pragma omp parallel for \
                num_threads(NT)                              // PRAG 2
    for(int i=0; i<NT; i++) printf("thrd no %d\n",thrd_no());

    #pragma omp parallel num_threads(NT)                     // PRAG 3-4
    #pragma omp for
    for(int i=0; i<NT; i++) printf("thrd no %d\n",thrd_no());

    #pragma omp parallel num_threads(NT)                     // PRAG 5
    {
       int no = thrd_no();
       if (no%2) { printf("thrd no %d is Odd \n",no);}
       else      { printf("thrd no %d is Even\n",no);}

       #pragma omp for                                    
       for(int i=0; i<NT; i++) printf("thrd no %d\n",thrd_no());
    }
},

void nested_apply(double A[100])
{
    #pragma omp tile sizes(10) \
            apply(intratile: unroll partial(2) apply(reverse))
    for (int i = 0; i < 100; ++i)
        A[i] = A[i] + 1;
},

void step1(double A[100])
{
   for (int i1 = 0; i1 < 10; ++i1)
   #pragma omp unroll partial(2) apply(reverse)
   for (int i2 = 0; i2 < 10; ++i2) {
      int i = i1 * 10 + i2;
      A[i] = A[i] + 1;
   }
},

void step2(double A[100])
{
   for (int i1 = 0; i1 < 10; ++i1)
   #pragma omp reverse
   for (int i2 = 0; i2 < 5; ++i2) {
      int i = i1 * 10 + i2 * 2;
      A[i] = A[i] + 1;
      ++i;
      A[i] = A[i] + 1;
   }
},

void step3(double A[100])
{
   for (int i1 = 0; i1 < 10; ++i1)
   for (int i2 = 4; i2 >= 0; --i2) {
      int i = i1 * 10 + i2 * 2;
      A[i] = A[i] + 1;
      ++i;
      A[i] = A[i] + 1;
   }
},

void span_apply(double A[128][128])
