      for (int i2 = 0; i2 < 16; ++i2)
      for (int j2 = 0; j2 < 16; ++j2) {
         int i = i1 * 16 + i2;
         int j = j1 * 16 + j2;
         A[i][j] = A[i][j] + 1;
      }
