{
   #pragma omp unroll partial(4)
   for (int i = 0; i < 128; ++i)
       A[i] = 0;
},

void unroll3_partial_equivalent(double A[])
{
   for (int i_iv = 0; i_iv < 32; ++i_iv) {
       A[i_iv * 4 + 0] = 0;
       A[i_iv * 4 + 1] = 0;
       A[i_iv * 4 + 2] = 0;
       A[i_iv * 4 + 3] = 0;
  }
},

