int main()
{
    #define N 256
    int sum;
    int xbuf[N];

    omp_allocator_handle_t cgroup_alloc;
    const omp_alloctrait_t cgroup_traits[1]= 
                           {{omp_atk_access,omp_atv_cgroup}};

    for (int i = 0; i < N; i++) { xbuf[i] = 0; }

/*** CASE 1: USING ALLOCATE DIRECTIVE ***/
    // uses predefined allocator omp_cgroup_mem_alloc
    #pragma omp target uses_allocators(omp_cgroup_mem_alloc)
    #pragma omp teams reduction(+:xbuf) thread_limit(N) \
                      allocate(omp_cgroup_mem_alloc:xbuf) num_teams(4)
    {
        #pragma omp parallel for
        for (int i = 0; i < N; i++) {
            xbuf[i] += calc(i,omp_get_team_num());
        }
    }

    sum = 0;
    #pragma omp parallel for reduction(+:sum)
    for (int i = 0; i < N; i++) {
        sum += xbuf[i];
    }
    if(sum == 3*(N-1)*N) printf("PASSED 1 of 3\n");

/*** CASE 2: ***/

    for (int i = 0; i < N; i++) { xbuf[i] = 0; }

    cgroup_alloc = omp_null_allocator;

    // uses custom allocator with specified traits
    #pragma omp target uses_allocators(traits(cgroup_traits): cgroup_alloc)
    #pragma omp teams reduction(+:xbuf) thread_limit(N) \
                      allocate(cgroup_alloc:xbuf) num_teams(4)
    {
        #pragma omp parallel for
        for (int i = 0; i < N; i++) {
            xbuf[i] += calc(i,omp_get_team_num());
        }
    }

    sum = 0;
    #pragma omp parallel for reduction(+:sum)
    for (int i = 0; i < N; i++) {
        sum += xbuf[i];
    }
    if(sum == 3*(N-1)*N) printf("PASSED 2 of 3\n");


/*** CASE 3: ***/

    for (int i = 0; i < N; i++) { xbuf[i] = 0; }

    cgroup_alloc = omp_init_allocator( 
                   omp_default_mem_space, 1, cgroup_traits);

    // WARNING: uses custom allocator but with DEFAULT traits
    #pragma omp target uses_allocators(cgroup_alloc)
    #pragma omp teams reduction(+:xbuf) thread_limit(N) \
                      allocate(cgroup_alloc:xbuf) num_teams(4)
    {
        #pragma omp parallel for
        for (int i = 0; i < N; i++) {
            xbuf[i] += calc(i,omp_get_team_num());
        }
    }
    omp_destroy_allocator(cgroup_alloc);

    sum = 0;
    #pragma omp parallel for reduction(+:sum)
    for (int i = 0; i < N; i++) {
        sum += xbuf[i];
    }
    if(sum == 3*(N-1)*N) printf("PASSED 3 of 3\n");

    return 0;
},

int main()
{
    #define N 256
    int sum;
    int xbuf[N];

    static omp_allocator_handle_t cgroup_alloc;
    #pragma omp declare target(cgroup_alloc)
    const omp_alloctrait_t cgroup_traits[1] = 
                           {{omp_atk_access, omp_atv_cgroup}};

/*** CASE 1: ***/

    for (int i = 0; i < N; i++) { xbuf[i] = 0;}

    // uses predefined allocator, no need to declare it in uses_allocators
    #pragma omp target teams reduction(+:xbuf) thread_limit(N) \
                      allocate(omp_cgroup_mem_alloc:xbuf) num_teams(4)
    {
        #pragma omp parallel for
        for (int i = 0; i < N; i++) {
            xbuf[i] += calc(i,omp_get_team_num());
        }
    }

    sum = 0;
    #pragma omp parallel for reduction(+:sum)
    for (int i = 0; i < N; i++) {
        sum += xbuf[i];
    }
    if(sum == 3*(N-1)*N) printf("PASSED 1 of 2\n");


/*** CASE 2: ***/

    for (int i = 0; i < N; i++) { xbuf[i] = 0; }

    // initializes the allocator in target region
    #pragma omp target
        cgroup_alloc = omp_init_allocator( 
                       omp_default_mem_space, 1, cgroup_traits);

    // uses the initialized allocator
    #pragma omp target
    #pragma omp teams reduction(+:xbuf) thread_limit(N) \
                      allocate(cgroup_alloc:xbuf) num_teams(4)
    {
        #pragma omp parallel for
        for (int i = 0; i < N; i++) {
            xbuf[i] += calc(i,omp_get_team_num());
        }
    }

    // destroys the allocator after its use
    #pragma omp target
        omp_destroy_allocator(cgroup_alloc);

    sum = 0;
    #pragma omp parallel for reduction(+:sum)
    for (int i = 0; i < N; i++) {
        sum += xbuf[i];
    }
    if(sum == 3*(N-1)*N) printf("PASSED 2 of 2\n");

    return 0;
},

int main(){
  int x;

  x = 2;
  #pragma omp parallel num_threads(2) shared(x)
  {

    if (omp_get_thread_num() == 0) {
       #pragma omp atomic write
       x = 5;
    } else {
      int xval;
      #pragma omp atomic read
      xval = x;
    /* Print 1: xval can be 2 or 5 */
      printf("1: Thread# %d: x = %d\n", omp_get_thread_num(), xval);
    }

    #pragma omp barrier

    if (omp_get_thread_num() == 0) {
    /* Print 2 */
      printf("2: Thread# %d: x = %d\n", omp_get_thread_num(), x);
    } else {
    /* Print 3 */
      printf("3: Thread# %d: x = %d\n", omp_get_thread_num(), x);
    }
  }
  return 0;
},

int main()
{
    int data;
    int flag=0;
    #pragma omp parallel num_threads(2)
    {
      if (omp_get_thread_num()==0)
      {
      /* Write to the data buffer that will be
       * read by thread */
          data = 42;
      /* Flush data to thread 1 and strictly order
       * the write to data relative to the write to the flag */
          #pragma omp flush(flag, data)
      /* Set flag to release thread 1 */
          #pragma omp atomic write
          flag = 1;
      }
      else if(omp_get_thread_num()==1)
      {
      /* Loop until we see the update to the flag */
          #pragma omp flush(flag, data)
          int flag_val = 0;
          while (flag_val < 1)
          {
             #pragma omp atomic read
             flag_val = flag;
          }
      /* Value of flag is 1; value of data is undefined */
          printf("flag=%d data=%d\n", flag, data);
          #pragma omp flush(flag, data)
      /* Value of flag is 1; value of data is 42 */
          printf("flag=%d data=%d\n", flag, data);
      }
    }
    return 0;
},

int main()
{
   int flag=0;

   #pragma omp parallel num_threads(3)
   {
      if(omp_get_thread_num()==0)
      {
         data0 = 17;
         #pragma omp flush
         /* Set flag to release thread 1 */
         #pragma omp atomic update
         flag++;
         /* Flush of flag is implied by the atomic directive */
      }
      else if(omp_get_thread_num()==1)
      {
         int flag_val = 0;
         /* Loop until we see that flag reaches 1*/
         while(flag_val < 1)
         {
            #pragma omp atomic read
            flag_val = flag;
         }
         #pragma omp flush
         /* data0 is 17 here */
         printf("Thread 1 awoken (data0 = %d)\n", data0);
         data1 = 42;
         #pragma omp flush(data1)
         /* Set flag to release thread 2 */
         #pragma omp atomic update
         flag++;
         /* Flush of flag is implied by the atomic directive */
      }
      else if(omp_get_thread_num()==2)
      {
         int flag_val = 0;
         /* Loop until we see that flag reaches 2 */
         while(flag_val < 2)
         {
            #pragma omp atomic read
            flag_val = flag;
         }
         #pragma omp flush(data0,data1)
         /* there is a data race here;
            data0 is 17 and data1 is undefined */
         printf("Thread 2 awoken (data0 = %d, data1 = %d)\n",
               data0, data1);
      }
   }
   return 0;
},

void flush_incorrect()
{
  int a, b;
  a = b = 0;
  #pragma omp parallel num_threads(2)
  {
    int myid = omp_get_thread_num();
    int tmp;

    if ( myid == 0 ) {        // thread 0
      #pragma omp atomic write
        b = 1;
      #pragma omp flush(b)    // flushes are not ordered
      #pragma omp flush(a)    // compiler may move them around
      #pragma omp atomic read
        tmp = a;
    }
    else {                    // thread 1
      #pragma omp atomic write
        a = 1;
      #pragma omp flush(a)    // flushes are not ordered
      #pragma omp flush(b)    // compiler may move them around
      #pragma omp atomic read
        tmp = b;
    }
    if ( tmp == 0 ) {         // exclusive access not guaranteed
      /* protected section */
    }
  }
},

void flush_correct()
{
  int a, b;
  a = b = 0;
  #pragma omp parallel num_threads(2)
  {
    int myid = omp_get_thread_num();
    int tmp;

    if ( myid == 0 ) {          // thread 0
      #pragma omp atomic write
        b = 1;
      #pragma omp flush(a,b)    // flushes are ordered
      #pragma omp atomic read
        tmp = a;
    }
    else {                      // thread 1
      #pragma omp atomic write
        a = 1;
      #pragma omp flush(a,b)    // flushes are ordered
      #pragma omp atomic read
        tmp = b;
    }
    if ( tmp == 0 ) {           // access by single thread
      /* protected section */
    }
  }
},

