#pragma omp parallel
    {
        int i;
#pragma omp for
        for (i = 0; i < 100; i++) {
#pragma omp task
            {
	// lock is shared by default in the task
	omp_set_lock(&lock);
                // Capture data for the following task
#pragma omp task
	// Task Scheduling Point 1
                { /* do work here */ }
                omp_unset_lock(&lock);
            }
        }
    }
    omp_destroy_lock(&lock);
},

