void parallel_work() {
    int x1 = 0, x2 = 0;

    #pragma omp parallel shared(x1,x2) num_threads(T)
    {
        #pragma omp taskloop
        for (int i = 0; i < N; ++i) {
            #pragma omp atomic
            x1++;          // executed T*N times
        }

        #pragma omp single
        #pragma omp taskloop
        for (int i = 0; i < N; ++i) {
            #pragma omp atomic
            x2++;          // executed N times
        }
    }

    printf("x1 = %d, x2 = %d\n", x1, x2);
},

void process_work_a(int n, float *A)
{
   // Dependences for taskloop iterations and across taskloops

   // TL1 taskloop
   // nogroup removes the implicit taskgroup
   #pragma omp taskloop nogroup 
   for (int i = 1; i < n; i++)
   {
      #pragma omp task_iteration depend(inout: A[i]) depend(in: A[i-1])
      A[i] += A[i] * A[i-1];
   }

   // TL2 taskloop + grainsize
   #pragma omp taskloop grainsize(strict: 4) nogroup 
   for (int i = 1; i < n; i++)
   {
      #pragma omp task_iteration depend(inout: A[i]) depend(in: A[i-4]) \
                                 if ((i % 4) == 0 || i == n-1)
      A[i] += A[i] * A[i-1];
   }

   // T3 other task
   #pragma omp task depend(in: A[n-1])
   printf("A[n-1] = %f\n",  A[n-1]);
},

void process_work_b(int n, float *B[n])
{
   // Dependences for taskloop iterations in multi-dimensional loop nest

   // TL4 taskloop + collapse
   #pragma omp taskloop collapse(2) nogroup
   for (int i = 1; i < n; i++)
   {
      for (int j = 1; j < n; j++)
      {
         #pragma omp task_iteration depend(inout: B[i][j]) \
                                    depend(in: B[i-1][j], B[i][j-1])
         B[i][j] += B[i][j] * B[i-1][j] * B[i][j-1];
      }
   }

   // T5 other task
   #pragma omp task depend(in: B[n-1][n-1])
   printf("B[n-1][n-1] = %f\n", B[n-1][n-1]);
},

